// Timbre oficial enviado pela Titular em 28/09/2026.
// Fonte integral: src/assets/capo-timbre-oficial.png (sem recorte ou deformação).
// Apenas convertido para JPEG para incorporação ao PDF.
const CAPO_DOCUMENT_LOGO_JPEG_BASE64 = ''
let cachedLogo: Uint8Array | null = null
export const CAPO_DOCUMENT_LOGO_WIDTH = 1448
export const CAPO_DOCUMENT_LOGO_HEIGHT = 237
export function getCapoDocumentLogoJpeg(): Uint8Array {
  if (cachedLogo) return cachedLogo
  const binary = globalThis.atob(CAPO_DOCUMENT_LOGO_JPEG_BASE64)
  const bytes = new Uint8Array(binary.length)
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index)
  cachedLogo = bytes
  return bytes
}
